import{_ as e,o as a,c as d,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Nuxt 到 Next.js 迁移","description":"列出 Nuxt 与 Next 在工单助手场景下的非等价能力，给出 composable→Hook、路由、状态迁移顺序与验收标准。","frontmatter":{"title":"Nuxt 到 Next.js 迁移","description":"列出 Nuxt 与 Next 在工单助手场景下的非等价能力，给出 composable→Hook、路由、状态迁移顺序与验收标准。","outline":[2,3],"article":{"type":"project","structure":"project"}},"headers":[],"relativePath":"ts-ai/integration/react-next/nuxt-nextjs-migration.md","filePath":"ts-ai/integration/react-next/nuxt-nextjs-migration.md","lastUpdated":1786083160000}'),r={name:"ts-ai/integration/react-next/nuxt-nextjs-migration.md"};function n(o,t,c,l,i,p){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="nuxt-到-next-js-迁移" tabindex="-1">Nuxt 到 Next.js 迁移 <a class="header-anchor" href="#nuxt-到-next-js-迁移" aria-label="Permalink to &quot;Nuxt 到 Next.js 迁移&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p><strong>本组是扩展，非主线。</strong> 仅当 <a href="/ts-ai/integration/react-next/nuxt-nextjs-selection">选型</a> 已结论为 Next，且 Nuxt 工单助手已按产品事件跑通时，才执行迁移。目标不是「逐文件翻译」，而是<strong>保持 Nest 契约不变</strong>，替换前端壳。</p><h2 id="_1-需求与范围" tabindex="-1">1. 需求与范围 <a class="header-anchor" href="#_1-需求与范围" aria-label="Permalink to &quot;1. 需求与范围&quot;">​</a></h2><h3 id="_1-1-迁移目标" tabindex="-1">1.1 迁移目标 <a class="header-anchor" href="#_1-1-迁移目标" aria-label="Permalink to &quot;1.1 迁移目标&quot;">​</a></h3><ul><li>浏览器仍消费：<code>run.started</code>、<code>message.delta</code>、<code>tool.started</code> / <code>completed</code> / <code>failed</code>、<code>run.completed</code> / <code>failed</code> / <code>cancelled</code>。</li><li><code>useAgentChat</code> 能力对等原 Vue composable：<code>send</code> / stream / <code>cancel</code>。</li><li>工单页：列表或详情可 SSR；Chat 为 Client。</li></ul><h3 id="_1-2-非目标" tabindex="-1">1.2 非目标 <a class="header-anchor" href="#_1-2-非目标" aria-label="Permalink to &quot;1.2 非目标&quot;">​</a></h3><ul><li>重写 Nest Agent 或改事件名。</li><li>借迁移强上 Vercel AI SDK（默认不上）。</li><li>一次迁移所有 Vue 后台页面（可分阶段）。</li></ul><h3 id="_1-3-前置冻结" tabindex="-1">1.3 前置冻结 <a class="header-anchor" href="#_1-3-前置冻结" aria-label="Permalink to &quot;1.3 前置冻结&quot;">​</a></h3><p>迁移开始前冻结：</p><ol><li>共享 <code>ProductEvent</code> 类型包（或等价 OpenAPI 生成类型）。</li><li>纯函数 <code>reduceAgentChat</code>（框架无关）。</li><li>Nest SSE 与取消行为的集成测试绿。</li></ol><h2 id="_2-非等价能力清单" tabindex="-1">2. 非等价能力清单 <a class="header-anchor" href="#_2-非等价能力清单" aria-label="Permalink to &quot;2. 非等价能力清单&quot;">​</a></h2><p>这些能力<strong>不能</strong>假设 1:1 存在，必须单独设计：</p><table tabindex="0"><thead><tr><th>Nuxt / Vue</th><th>Next / React</th><th>迁移策略</th></tr></thead><tbody><tr><td><code>ref</code> / 深层响应式就地改</td><td><code>useState</code> 不可变更新</td><td>统一走 reducer，禁止就地改 React state</td></tr><tr><td>composable 可在非组件调用</td><td>Hook 仅组件/Hook 顶层</td><td>把非 UI 逻辑抽成纯函数</td></tr><tr><td><code>onScopeDispose</code></td><td><code>useEffect</code> cleanup</td><td>Chat 根组件挂载 cleanup → <code>cancel()</code></td></tr><tr><td>Nuxt <code>useState</code> 跨组件键</td><td>React Context / props</td><td>明确 Chat 状态所有权，避免双实例</td></tr><tr><td><code>middleware</code> 路由守卫</td><td>Next middleware / Server 门闸</td><td>重做鉴权入口，勿抄 Nuxt 文件</td></tr><tr><td><code>nitro</code> 服务端路由</td><td>Route Handler</td><td>API 代理逐条移植</td></tr><tr><td><code>routeRules</code> 代理</td><td><code>rewrites</code> / BFF</td><td>按 <a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接文</a> 选型</td></tr><tr><td>Nuxt 插件 / 模块</td><td>无直接等价</td><td>换成 provider 或 lib 初始化</td></tr><tr><td><code>&lt;ClientOnly&gt;</code></td><td>动态 <code>ssr: false</code> 或天然 Client 文件</td><td>Chat 直接 <code>&quot;use client&quot;</code></td></tr><tr><td>Pinia store</td><td>Context 或外部 store</td><td>Chat 优先局部 Hook；全局再引库</td></tr><tr><td>Vue 单文件样式</td><td>CSS Modules / 现有 React 体系</td><td>不阻塞功能迁移</td></tr></tbody></table><p><strong>等价且应原样保留：</strong> 产品事件、REST 路径、错误码、Abort 语义、假事件单测。</p><h2 id="_3-架构映射" tabindex="-1">3. 架构映射 <a class="header-anchor" href="#_3-架构映射" aria-label="Permalink to &quot;3. 架构映射&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nuxt 页 + useAgentChat(composable) + nitro 代理</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>Next app/tickets/[id]/page (RSC 壳)</span></span>
<span class="line"><span>  + TicketAssistantChat (client Hook)</span></span>
<span class="line"><span>  + rewrites 或 Route Handler</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>同一 Nest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>共享包建议：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/product-events/</span></span>
<span class="line"><span>  src/types.ts          # ProductEvent</span></span>
<span class="line"><span>  src/reduce-agent-chat.ts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Nuxt 与 Next 都依赖该包，避免两套 reducer。</p><h2 id="_4-实现-分域迁移" tabindex="-1">4. 实现：分域迁移 <a class="header-anchor" href="#_4-实现-分域迁移" aria-label="Permalink to &quot;4. 实现：分域迁移&quot;">​</a></h2><h3 id="_4-1-composable-→-hook" tabindex="-1">4.1 Composable → Hook <a class="header-anchor" href="#_4-1-composable-→-hook" aria-label="Permalink to &quot;4.1 Composable → Hook&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>动作</th></tr></thead><tbody><tr><td>1</td><td>抽出 <code>reduceAgentChat</code> + <code>readSseStream</code> 到共享包</td></tr><tr><td>2</td><td>Nuxt composable 改为调用共享包（验证无回归）</td></tr><tr><td>3</td><td>按 <a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks 文</a> 实现 <code>useAgentChat</code></td></tr><tr><td>4</td><td>对齐返回字段名：<code>messages</code>、<code>runStatus</code>、<code>send</code>、<code>cancel</code>、<code>isBusy</code></td></tr></tbody></table><p>对照见 <a href="/ts-ai/integration/react-next/vue-react-state-comparison">状态模型对照</a>。</p><h3 id="_4-2-路由" tabindex="-1">4.2 路由 <a class="header-anchor" href="#_4-2-路由" aria-label="Permalink to &quot;4.2 路由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nuxt</th><th>Next App Router</th></tr></thead><tbody><tr><td><code>pages/tickets/[id].vue</code></td><td><code>app/tickets/[id]/page.tsx</code></td></tr><tr><td><code>pages/tickets/index.vue</code></td><td><code>app/tickets/page.tsx</code></td></tr><tr><td><code>middleware/auth.ts</code></td><td><code>middleware.ts</code> + Server 校验</td></tr><tr><td><code>server/routes/api/nest/...</code></td><td><code>app/api/nest/.../route.ts</code> 或 rewrite</td></tr></tbody></table><p>动态段、布局（<code>layout.tsx</code>）按信息架构重建，不要依赖 Vue Router 的导航守卫语义。</p><h3 id="_4-3-状态" tabindex="-1">4.3 状态 <a class="header-anchor" href="#_4-3-状态" aria-label="Permalink to &quot;4.3 状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原状态</th><th>迁移后</th></tr></thead><tbody><tr><td>Chat 消息 / Run</td><td>仅存在于 <code>useAgentChat</code> 实例</td></tr><tr><td>当前工单摘要</td><td>RSC fetch 或 React Query（按团队现栈）</td></tr><tr><td>用户会话</td><td>Cookie / Next auth 方案；与 Nest Token 策略在对接文中选定</td></tr></tbody></table><p>禁止：RSC 取一次 messages 当「实时源」。实时只来自 SSE。</p><h3 id="_4-4-ui-组件" tabindex="-1">4.4 UI 组件 <a class="header-anchor" href="#_4-4-ui-组件" aria-label="Permalink to &quot;4.4 UI 组件&quot;">​</a></h3><p>优先迁移：</p><ol><li>消息列表与流式气泡（只依赖 <code>messages</code>）。</li><li>发送条与取消按钮（<code>send</code> / <code>cancel</code> / <code>isBusy</code>）。</li><li>工具行（<code>role === &#39;tool&#39;</code>）。</li></ol><p>Markdown、上传、HITL 确认可第二波；协议与 Hook 第一波必须绿。</p><h2 id="_5-迁移顺序-推荐" tabindex="-1">5. 迁移顺序（推荐） <a class="header-anchor" href="#_5-迁移顺序-推荐" aria-label="Permalink to &quot;5. 迁移顺序（推荐）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 冻结 ProductEvent + reduce 单测</span></span>
<span class="line"><span>2. Nuxt 改用共享 reduce（回归）</span></span>
<span class="line"><span>3. 新建 Next 应用骨架 + 鉴权门闸</span></span>
<span class="line"><span>4. 实现 useAgentChat + 假事件页面</span></span>
<span class="line"><span>5. 接通 Nest（先直连，再 rewrite/BFF）</span></span>
<span class="line"><span>6. 迁移工单详情壳（SSR）+ Chat 岛</span></span>
<span class="line"><span>7. 代理与超时按生产配置验证</span></span>
<span class="line"><span>8. 切流量；Nuxt Chat 路由只读或下线</span></span>
<span class="line"><span>9. 其余 Vue 页面按需迁移</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>不要</strong>从第 6 步之前切生产流量。</p><h3 id="_5-1-并存期约定" tabindex="-1">5.1 并存期约定 <a class="header-anchor" href="#_5-1-并存期约定" aria-label="Permalink to &quot;5.1 并存期约定&quot;">​</a></h3><p>迁移窗口内允许 Nuxt 与 Next <strong>短暂并存</strong>：</p><table tabindex="0"><thead><tr><th>约定</th><th>说明</th></tr></thead><tbody><tr><td>同一 Nest</td><td>禁止为 Next 开第二套事件名</td></tr><tr><td>共享 reduce</td><td>CI 对 <code>packages/product-events</code> 跑单测</td></tr><tr><td>流量开关</td><td>按租户或工单 ID 百分比切到 Next</td></tr><tr><td>观测</td><td>对比两侧 <code>run.failed</code> / <code>cancelled</code> 率</td></tr></tbody></table><p>并存超过一个发布周期仍无切流计划时，应停止双端功能开发，只留一侧。</p><h2 id="_6-测试" tabindex="-1">6. 测试 <a class="header-anchor" href="#_6-测试" aria-label="Permalink to &quot;6. 测试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>内容</th></tr></thead><tbody><tr><td>单测</td><td><code>reduceAgentChat</code>：delta 拼接、tool 失败、终态</td></tr><tr><td>组件测</td><td>发送后出现 user 消息；busy 时禁用输入</td></tr><tr><td>集成</td><td>对 Nest 的 create + stream；取消后 DB/状态 cancelled</td></tr><tr><td>契约</td><td>事件名与 <a href="/ts-ai/backend/api-realtime/openapi-contracts">OpenAPI / 事件文</a> 一致</td></tr><tr><td>性能冒烟</td><td>长回复下滚动与输入仍可用（可加 <code>startTransition</code>，非必须）</td></tr></tbody></table><h2 id="_7-交付与验收" tabindex="-1">7. 交付与验收 <a class="header-anchor" href="#_7-交付与验收" aria-label="Permalink to &quot;7. 交付与验收&quot;">​</a></h2><h3 id="_7-1-功能验收-工单助手" tabindex="-1">7.1 功能验收（工单助手） <a class="header-anchor" href="#_7-1-功能验收-工单助手" aria-label="Permalink to &quot;7.1 功能验收（工单助手）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>标准</th><th>通过</th></tr></thead><tbody><tr><td>M1</td><td>打开工单详情可见 SSR 标题与 Chat 岛</td><td>☐</td></tr><tr><td>M2</td><td>发送「查询 T-1024」出现 user 消息</td><td>☐</td></tr><tr><td>M3</td><td>收到 <code>message.delta</code> 气泡增量增长</td><td>☐</td></tr><tr><td>M4</td><td>有工具时 UI 展示 started → completed/failed</td><td>☐</td></tr><tr><td>M5</td><td><code>run.completed</code> 后 <code>isBusy === false</code></td><td>☐</td></tr><tr><td>M6</td><td>中途取消 → UI <code>cancelled</code>，Nest Run cancelled</td><td>☐</td></tr><tr><td>M7</td><td><code>run.failed</code> 展示 <code>code</code> / <code>message</code></td><td>☐</td></tr><tr><td>M8</td><td>无 Token 时行为与 Nuxt 一致（401）</td><td>☐</td></tr><tr><td>M9</td><td>刷新页不丢「已落库」历史（若产品有历史接口）</td><td>☐</td></tr><tr><td>M10</td><td>不在 RSC 日志中出现长挂起的 SSE fetch</td><td>☐</td></tr></tbody></table><h3 id="_7-2-工程验收" tabindex="-1">7.2 工程验收 <a class="header-anchor" href="#_7-2-工程验收" aria-label="Permalink to &quot;7.2 工程验收&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>标准</th><th>通过</th></tr></thead><tbody><tr><td>E1</td><td>共享包被 Nuxt（若并存）与 Next 同时引用</td><td>☐</td></tr><tr><td>E2</td><td>对接 checklist 与 <a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">Next 对接 Nest</a> 全文勾完</td><td>☐</td></tr><tr><td>E3</td><td>未引入 AI SDK，或已书面批准适配层</td><td>☐</td></tr><tr><td>E4</td><td>生产代理超时与心跳已配置</td><td>☐</td></tr><tr><td>E5</td><td>回滚方案：DNS / 路由可切回 Nuxt Chat</td><td>☐</td></tr></tbody></table><h3 id="_7-3-退出标准" tabindex="-1">7.3 退出标准 <a class="header-anchor" href="#_7-3-退出标准" aria-label="Permalink to &quot;7.3 退出标准&quot;">​</a></h3><p>M1–M8 与 E1–E5 全部通过，方可宣布「Chat 迁移完成」。其余页面迁移另立迭代。</p><h2 id="_8-风险与回退" tabindex="-1">8. 风险与回退 <a class="header-anchor" href="#_8-风险与回退" aria-label="Permalink to &quot;8. 风险与回退&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>缓解</th></tr></thead><tbody><tr><td>双前端双 reducer</td><td>强制共享包；CI 类型检查</td></tr><tr><td>rewrite SSE 静默缓冲</td><td>用取消与增量可见性测试；不行改 BFF</td></tr><tr><td>Strict Mode 双请求</td><td>cleanup abort；文档告知开发态现象</td></tr><tr><td>进度压力下改 Nest 事件</td><td><strong>拒绝</strong>；前后端契约冻结</td></tr></tbody></table><p>回退：保留 Nuxt 部署与 Nest 不变；Next 仅下线入口。</p><h2 id="_9-总结" tabindex="-1">9. 总结 <a class="header-anchor" href="#_9-总结" aria-label="Permalink to &quot;9. 总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>内容</th></tr></thead><tbody><tr><td>契约不变</td><td>产品事件与 Nest 路径冻结</td></tr><tr><td>先共享逻辑</td><td>reduce / 类型先于 UI</td></tr><tr><td>Chat 必 Client</td><td>App Router 边界不可破</td></tr><tr><td>验收对等</td><td>与 Nuxt 能力 checklist 对齐</td></tr></tbody></table><p>迁移完成后用 <a href="/ts-ai/integration/assembly/assembly-recipes-checklist">组装配方与自检</a> 勾选 React 扩展项；日常开发仍以 Nuxt 主线文档服务 Vue 团队，本组仅服务已迁栈团队。</p>`,56)])])}const b=e(r,[["render",n]]);export{u as __pageData,b as default};
